    private fun parseLaps(data: String): List<OpenF1Lap> {
        val tokens = data.split(';')
        val result = ArrayList<OpenF1Lap>(tokens.size)
        for (token in tokens) {
            if (token.isBlank()) continue
            val parts = token.split(',')
            if (parts.size >= 6) {
                val d = parts[0].toIntOrNull() ?: continue
                val n = parts[1].toIntOrNull() ?: continue
                val dur = (parts[2].toIntOrNull() ?: 8500) / 100.0
                val s1 = (parts[3].toIntOrNull() ?: 2750) / 100.0
                val s2 = (parts[4].toIntOrNull() ?: 2850) / 100.0
                val s3 = (parts[5].toIntOrNull() ?: 2900) / 100.0
                result.add(
                    OpenF1Lap(
                        driverNumber = d,
                        lapNumber = n,
                        lapDuration = dur,
                        durationSector1 = s1,
                        durationSector2 = s2,
                        durationSector3 = s3
                    )
                )
            }
        }
        return result
    }

    private fun parseStints(data: String): List<OpenF1Stint> {
        val tokens = data.split(';')
        val result = ArrayList<OpenF1Stint>(tokens.size)
        for (token in tokens) {
            if (token.isBlank()) continue
            val parts = token.split(',')
            if (parts.size >= 6) {
                val d = parts[0].toIntOrNull() ?: continue
                val sNum = parts[1].toIntOrNull() ?: continue
                val start = parts[2].toIntOrNull() ?: 1
                val end = parts[3].toIntOrNull() ?: 1
                val compound = parts[4]
                val age = parts[5].toIntOrNull() ?: 0
                result.add(
                    OpenF1Stint(
                        driverNumber = d,
                        stintNumber = sNum,
                        lapStart = start,
                        lapEnd = end,
                        compound = compound,
                        tyreAgeAtStart = age
                    )
                )
            }
        }
        return result
    }

